## Purpose

This question evaluates practical accessibility implementation in SwiftUI, lightweight persistence strategies, and architectural awareness for beginner-level candidates.

## Key Concepts

- SwiftUI accessibility modifiers (`accessibilityLabel`, `accessibilityHint`, `accessibilityValue`)
- Codable persistence to the app's Documents directory
- MVVM architecture with a minimal data model
- Dynamic Type support and color-contrast considerations (WCAG AA compliance)

## Code Example

```swift
struct Note: Codable, Identifiable {
    let id: UUID
    let title: String
    let tag: String  // e.g., "blue", "red", "green"
}

class NotesStore: ObservableObject {
    @Published var notes: [Note] = []

    private var documentsURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("notes.json")
    }

    init() { loadNotes() }

    func loadNotes() {
        guard let data = try? Data(contentsOf: documentsURL),
              let decoded = try? JSONDecoder().decode([Note].self, from: data) else { return }
        notes = decoded
    }

    func saveNotes() {
        guard let data = try? JSONEncoder().encode(notes) else { return }
        try? data.write(to: documentsURL)
    }
}

struct NoteRow: View {
    let note: Note

    var body: some View {
        HStack {
            VStack(alignment: .leading) {
                Text(note.title)
                    .font(.body)
                    .dynamicTypeSize(...(.accessibility3))

                Text(note.tag.capitalized)
                    .font(.caption)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 4)
                    .background(tagColor(note.tag))
                    .foregroundColor(tagTextColor(note.tag))
                    .clipShape(Capsule())
            }
            Spacer()
        }
        .padding(.vertical, 8)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(note.title), tagged \(note.tag)")
        .accessibilityHint("Double tap to open this note")
    }

    private func tagColor(_ tag: String) -> Color {
        switch tag.lowercased() {
        case "blue":   return Color(red: 0.0, green: 0.48, blue: 1.0)
        case "green":  return Color(red: 0.18, green: 0.8, blue: 0.25)
        case "red":    return Color(red: 0.9, green: 0.2, blue: 0.2)
        default:       return .gray
        }
    }

    private func tagTextColor(_ tag: String) -> Color {
        return .white  // High contrast against all tag colors
    }
}

struct ContentView: View {
    @StateObject private var store = NotesStore()

    var body: some View {
        NavigationStack {
            List(store.notes) { note in
                NoteRow(note: note)
            }
        }
    }
}
```

## Test Plan

1. **Accessibility Audit**: Verify VoiceOver reads labels and hints correctly for each row
2. **Dynamic Type**: Test with largest accessibility sizes to confirm layout remains usable
3. **Contrast Validation**: Use accessibility inspector or contrast checker to verify WCAG AA compliance (4.5:1 ratio)
4. **Persistence**: Confirm notes survive app restart by adding a note, killing the app, and relaunching
5. **Unit Tests**: Test `Note` Codable encoding/decoding and `NotesStore` save/load roundtrip

## Why This Is Asked

This question validates core competencies in data modeling, local persistence, data aggregation, SwiftUI visualization, and crash-safe resume behavior, along with the candidate's ability to plan basic testing.

## Key Concepts

- Codable and FileManager for JSON persistence
- SwiftUI Canvas for custom chart rendering
- Date normalization to day granularity for aggregation
- Atomic file writes for crash safety
- Lightweight test planning

## Code Example

```swift
struct MoodEntry: Codable, Identifiable {
    let id: UUID
    let date: Date
    let mood: Int // 1-5 scale
    let note: String?
}
```

```swift
class MoodStore: ObservableObject {
    @Published var entries: [MoodEntry] = []

    private let url: URL
    private let fileManager = FileManager.default
    private let queue = DispatchQueue(label: "com.moodgraph.persistence")

    init() {
        let documentsURL = fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
        self.url = documentsURL.appendingPathComponent("mood_entries.json")
        load()
    }

    func addEntry(mood: Int, note: String?) {
        let entry = MoodEntry(id: UUID(), date: Date(), mood: mood, note: note)
        entries.append(entry)
        save()
    }

    private func save() {
        queue.async { [weak self] in
            guard let self = self else { return }
            do {
                let data = try JSONEncoder().encode(self.entries)
                let tempURL = self.url.deletingLastPathComponent()
                    .appendingPathComponent("mood_entries_temp.json")
                try data.write(to: tempURL, options: .atomic)
                try fileManager.moveItem(at: tempURL, to: self.url)
            } catch {
                print("Failed to save: \(error)")
            }
        }
    }

    private func load() {
        guard fileManager.fileExists(atPath: url.path) else { return }
        do {
            let data = try Data(contentsOf: url)
            entries = try JSONDecoder().decode([MoodEntry].self, from: data)
        } catch {
            print("Failed to load: \(error)")
        }
    }

    func dailyAverages() -> [(date: Date, average: Double)] {
        let calendar = Calendar.current
        let grouped = Dictionary(grouping: entries) { entry in
            calendar.startOfDay(for: entry.date)
        }
        return grouped.map { (date, entries) in
            let avg = Double(entries.reduce(0) { $0 + $1.mood }) / Double(entries.count)
            return (date: date, average: avg)
        }.sorted { $0.date < $1.date }
    }
}
```

```swift
struct MoodChartView: View {
    let data: [(date: Date, average: Double)]

    var body: some View {
        Canvas { context, size in
            guard data.count > 1 else { return }
            let maxMood: Double = 5.0
            let stepX = size.width / CGFloat(data.count - 1)

            var path = Path()
            for (index, point) in data.enumerated() {
                let x = CGFloat(index) * stepX
                let y = size.height - (CGFloat(point.average / maxMood) * size.height)
                if index == 0 {
                    path.move(to: CGPoint(x: x, y: y))
                } else {
                    path.addLine(to: CGPoint(x: x, y: y))
                }
            }

            context.stroke(path, with: .color(.blue), lineWidth: 2)
        }
        .frame(height: 200)
    }
}
```

## Test Plan

1. **Unit Tests**
   - Verify MoodEntry encoding/decoding roundtrip
   - Test dailyAverages() with known input data
   - Validate mood range enforcement (1-5)

2. **Integration Tests**
   - Add entry, verify file exists in Documents
   - Restart app, verify entries persist
   - Add multiple entries same day, verify correct average

3. **UI Tests**
   - Verify mood picker limits selection to 1-5
   - Confirm note field is optional
   - Validate chart renders non-empty data

## Why This Is Asked
Tests practical iOS fundamentals: Codable data models, file-based persistence with atomic writes, and SwiftUI data flow. It also exercises UX concerns like debounce for responsiveness and accessibility considerations.

## Key Concepts
- Codable data model for Note with title, body, tags, and date
- File I/O in Documents with atomic write pattern
- SwiftUI state management using @Published and binding for filters
- Combine debouncing for search input
- Tag-based filtering logic and accessibility labeling

## Code Example
